const { sbRequest, getOrCreateConversation, saveMessage } = require('/home/node/scripts/cvpro-helpers.js');
const threeDaysAgo = new Date(Date.now() - 3 * 86400000).toISOString();
const staleLeads = await sbRequest(
  $http,
  'GET',
  `/rest/v1/customers?lead_stage=in.(offer_sent,negotiation)&last_interaction=lt.${threeDaysAgo}&phone_number=not.is.null&select=id,phone_number,full_name`
);
const results = [];
for (const lead of staleLeads || []) {
  const followupMsg = `مرحباً ${lead.full_name || 'عميلنا'}، لم نسمع منك بخصوص عرضنا. هل تريد مساعدة إضافية؟ لدينا خصم 15% اليوم فقط!`;
  try {
    await $http.request({
      method: 'POST',
      url: `https://graph.facebook.com/v21.0/${process.env.WHATSAPP_PHONE_NUMBER_ID}/messages`,
      headers: { Authorization: `Bearer ${process.env.WHATSAPP_ACCESS_TOKEN}`, 'Content-Type': 'application/json' },
      body: { messaging_product: 'whatsapp', to: lead.phone_number, type: 'text', text: { body: followupMsg } },
    });
    const conv = await getOrCreateConversation($http, lead.id, 'whatsapp');
    await saveMessage($http, conv.id, 'outbound', followupMsg, { is_ai_generated: true });
    results.push({ leadId: lead.id, followupSent: true });
  } catch (_) {
    results.push({ leadId: lead.id, followupSent: false });
  }
}
return [{ json: results }];
